INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"সেমি-রিজিড পেভমেন্ট","side":"right","image":"/semi.webp","caption":"","linkHref":"","linkLabel":"","body":"<p>নমনীয়তা ও স্থায়িত্বের সমন্বয়ে একটি হাইব্রিড পেভমেন্ট ব্যবস্থা, যা এই প্রকল্পে বাংলাদেশে প্রথম প্রবর্তিত হয়েছে।</p><p><strong>কারিগরি সুবিধা</strong></p><ul><li>ভারী বাণিজ্যিক যানবাহনের জন্য উচ্চ ভারবহন ক্ষমতা</li><li>প্রচলিত অ্যাসফল্ট পেভমেন্টের তুলনায় বেশি টেকসই</li><li>গ্রীষ্মমণ্ডলীয় আবহাওয়ায় রাটিং ও বিকৃতি প্রতিরোধে ভালো</li><li>প্রকল্পের পুরো মেয়াদে কম রক্ষণাবেক্ষণ</li></ul><p><strong>নির্মাণ প্রক্রিয়া</strong></p><ul><li>আধুনিক যন্ত্রপাতিতে নিখুঁত পুরুত্ব নিয়ন্ত্রণ</li><li>অকালে ফাটল রোধে বিশেষ কিউরিং পদ্ধতি</li><li>নির্মাণকালে নিরবচ্ছিন্ন মান পর্যবেক্ষণ</li><li>সর্বোত্তম কার্যকারিতার জন্য কম্পিউটারাইজড মিশ্রণ নকশা</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"半刚性路面","side":"right","image":"/semi.webp","caption":"","linkHref":"","linkLabel":"","body":"<p>一种兼具柔性与耐久性的复合路面结构，由本项目首次引入孟加拉国。</p><p><strong>技术优势</strong></p><ul><li>承载能力高，适合重型商用车辆</li><li>耐久性优于传统沥青路面</li><li>在热带气候下抗车辙和抗变形能力更强</li><li>全寿命周期养护需求更低</li></ul><p><strong>施工工艺</strong></p><ul><li>采用先进设备精确控制厚度</li><li>专门养生工艺防止早期开裂</li><li>施工全过程持续质量监控</li><li>计算机配合比设计，确保最佳性能</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

-- project · media-prose · Technology benefits
SET @b = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id` JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
  WHERE p.`slug` = 'project' AND b.`type` = 'media-prose' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.heading')) = 'Technology benefits' LIMIT 1);
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"প্রযুক্তির সুফল","side":"left","image":"/cp.webp","caption":"","linkHref":"","linkLabel":"","body":"<ul><li><strong>দীর্ঘ আয়ু</strong> — প্রচলিত পেভমেন্টের ১৫–২০ বছরের তুলনায় ৩০+ বছর সেবা</li><li><strong>ব্যয় সাশ্রয়</strong> — প্রাথমিক বিনিয়োগ বেশি, তবে পুরো মেয়াদে রক্ষণাবেক্ষণ খরচ অনেক কম</li><li><strong>আবহাওয়া সহনশীলতা</strong> — বর্ষা মৌসুম ও চরম তাপমাত্রার পরিবর্তনে উন্নত কার্যকারিতা</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"技术效益","side":"left","image":"/cp.webp","caption":"","linkHref":"","linkLabel":"","body":"<ul><li><strong>使用寿命更长</strong>——设计使用寿命30年以上，传统路面为15–20年</li><li><strong>成本效益</strong>——初期投资较高，但全寿命周期养护成本显著降低</li><li><strong>耐候性强</strong>——在季风季节和极端温度变化下表现更优</li></ul>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

-- project · rich-text · Vision and mission
SET @b = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id` JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
  WHERE p.`slug` = 'project' AND b.`type` = 'rich-text' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.heading')) = 'Vision and mission' LIMIT 1);
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"রূপকল্প ও লক্ষ্য","body":"<p><strong>রূপকল্প।</strong> বিশ্বমানের একটি এক্সপ্রেসওয়ে গড়ে তুলে বাংলাদেশের পরিবহন অবকাঠামোয় রূপান্তর আনা, যা ভবিষ্যৎ উন্নয়ন প্রকল্পের দৃষ্টান্ত হবে, সংযোগ বাড়াবে এবং অর্থনৈতিক প্রবৃদ্ধিতে সহায়তা করবে।</p><p><strong>লক্ষ্য।</strong> বাংলাদেশের পরিবহন নেটওয়ার্কে নিরাপত্তা, দক্ষতা ও টেকসইতার নতুন মান স্থাপনকারী একটি রূপান্তরমূলক এক্সপ্রেসওয়ে সরবরাহ করা — উদ্ভাবনী প্রকৌশল সমাধান বাস্তবায়ন, জ্ঞান স্থানান্তর ও সক্ষমতা বৃদ্ধি, এবং করিডোর বরাবর অর্থনৈতিক উন্নয়নের সুযোগ সৃষ্টি।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"愿景与使命","body":"<p><strong>愿景。</strong>打造世界一流的高速公路，推动孟加拉国交通基础设施转型，为未来发展项目树立典范，增强互联互通，支持经济增长。</p><p><strong>使命。</strong>建成一条在安全、效率和可持续性方面为孟加拉国交通网络树立新标准的高速公路——应用创新工程方案，促进知识转移和能力建设，并为走廊沿线创造经济发展机会。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

