  WHERE p.`slug` = 'about/governance' AND b.`type` = 'stat-row' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.stats[0].label')) = 'Road PPP in Bangladesh' LIMIT 1);
