SET @b = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id` JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
  WHERE p.`slug` = 'about/governance' AND b.`type` = 'card-grid' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.heading')) = 'Partners' LIMIT 1);
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"অংশীদার","intro":"","items":[{"meta":"প্রধান বিনিয়োগকারী ও ঠিকাদার","title":"সিচুয়ান রোড অ্যান্ড ব্রিজ গ্রুপ (SRBG)","body":"৬০% ইকুইটির প্রধান বেসরকারি বিনিয়োগকারী; প্রধান ইপিসি ঠিকাদার; সেমি-রিজিড পেভমেন্ট ও রিইনফোর্সড রিটেইনিং ওয়াল প্রবর্তন করেছে। শুদাও ইনভেস্টমেন্ট গ্রুপের (SDIG) সদস্য। ১,০০০-এর বেশি স্থানীয় শ্রমিক নিয়োজিত।"},{"meta":"স্থানীয় অংশীদার, ৩০%","title":"শামীম এন্টারপ্রাইজ লিমিটেড (SEL)","body":"স্থানীয় জ্ঞান, নির্মাণ দক্ষতা, নিয়ন্ত্রক বিধি পরিপালন ও স্থানীয় সরবরাহ ব্যবস্থা দিয়ে সহায়তাকারী প্রধান স্থানীয় বেসরকারি অংশীদার।"},{"meta":"স্থানীয় অংশীদার, ১০%","title":"ইউডিসি কনস্ট্রাকশন লিমিটেড","body":"অতিরিক্ত স্থানীয় নির্মাণ সক্ষমতা ও অংশীজন সমন্বয়ে সহায়তাকারী দ্বিতীয় বাংলাদেশি অংশীদার। দুই স্থানীয় অংশীদারের সম্মিলিত অংশ ৪০%।"},{"meta":"পিপিপি সহায়তাকারী","title":"পাবলিক-প্রাইভেট পার্টনারশিপ কর্তৃপক্ষ (PPPA)","body":"২০১২ সালে প্রকল্পটির নীতিগত অনুমোদন দেয় এবং ডিসেম্বর ২০১৮-এ চুক্তি স্বাক্ষর পর্যন্ত পিপিপি চুক্তির কাঠামো নির্ধারণে সহায়তা করে। প্রধানমন্ত্রীর কার্যালয়ের অধীনে পরিচালিত।"},{"meta":"চুক্তিকারী কর্তৃপক্ষ","title":"সড়ক ও জনপথ অধিদপ্তর (RHD)","body":"সরকারি খাতের ক্লায়েন্ট ও কনসেশন প্রদানকারী; ভূমি অধিগ্রহণ ও পুনর্বাসন সম্পন্ন করে এবং ভায়াবিলিটি গ্যাপ ফান্ডিং প্রদান করে। ২৫ বছরের কনসেশন শেষে সম্পদ ফেরত পায়।"},{"meta":"প্রধান বিদেশি ঋণদাতা","title":"চায়না ডেভেলপমেন্ট ব্যাংক (CDB)","body":"এপ্রিল ২০২১-এ স্বাক্ষরিত অর্থায়ন চুক্তির আওতায় DBEDC-কে ১,৬১৪ কোটি টাকা ঋণ দেয়, যা ৪১২ মিলিয়ন মার্কিন ডলারের অর্থায়ন প্যাকেজ সম্পূর্ণ করে।"},{"meta":"দেশীয় ঋণদাতা","title":"বাংলাদেশ ইনফ্রাস্ট্রাকচার ফাইন্যান্স ফান্ড লিমিটেড (BIFFL)","body":"রাষ্ট্রায়ত্ত অবকাঠামো অর্থায়নকারী; ২০২০ সালের এডিবি-সমর্থিত ঋণ সুবিধার আওতায় DBEDC-কে ১,০৭৫ কোটি টাকার ঋণ সুবিধা, যার প্রথম কিস্তি ৪২.৫ কোটি টাকা এপ্রিল ২০২২-এ ছাড় করা হয়।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"合作伙伴","intro":"","items":[{"meta":"牵头投资方和承包商","title":"四川路桥集团（SRBG）","body":"持股60%的牵头私营投资方；EPC总承包商；引入半刚性路面和加筋挡土墙技术。蜀道投资集团（SDIG）成员企业。雇用当地员工逾1,000人。"},{"meta":"本地合作方，30%","title":"Shamim Enterprise Ltd（SEL）","body":"主要本地私营合作方，提供本地经验、施工能力、合规支持和本地供应链。"},{"meta":"本地合作方，10%","title":"UDC Construction Ltd","body":"第二家孟加拉国合作方，提供补充施工能力并协调相关方。两家本地合作方合计持股40%。"},{"meta":"PPP促进机构","title":"政府与社会资本合作管理局（PPPA）","body":"2012年原则批准本项目，并协助构建PPP协议直至2018年12月签约。隶属总理办公室。"},{"meta":"合同授予方","title":"孟加拉国公路局（RHD）","body":"公共部门业主及特许权授予方；负责征地和安置，并提供可行性缺口补助。25年特许经营期满后收回资产。"},{"meta":"主要外国贷款方","title":"国家开发银行（CDB）","body":"根据2021年4月签署的融资协议向DBEDC提供161.4亿塔卡贷款，完成4.12亿美元融资安排。"},{"meta":"国内贷款方","title":"孟加拉国基础设施融资基金有限公司（BIFFL）","body":"国有基础设施融资机构；依据2020年亚行支持的信贷额度向DBEDC提供107.5亿塔卡贷款，首期4.25亿塔卡于2022年4月发放。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;

-- about/governance · rich-text · Financing
SET @b = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id` JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
  WHERE p.`slug` = 'about/governance' AND b.`type` = 'rich-text' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.heading')) = 'Financing' LIMIT 1);
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"অর্থায়ন","body":"<p>বাংলাদেশ সরকারের ভায়াবিলিটি গ্যাপ ফান্ডিং প্রাথমিকভাবে ২২৪ কোটি টাকা ছিল, পরে সংশোধন করে ৬৭৪ কোটি টাকা করা হয়। চায়না ডেভেলপমেন্ট ব্যাংক ১,৬১৪ কোটি টাকা ঋণ দেয় (চুক্তি এপ্রিল ২০২১); BIFFL ১,০৭৫ কোটি টাকা ঋণ দেয়, যার প্রথম কিস্তি ৪২.৫ কোটি টাকা এপ্রিল ২০২২-এ ছাড় করা হয়। মোট প্যাকেজ ৪১২ মিলিয়ন মার্কিন ডলার (প্রায় ৩,৫৮৫–৩,৭২৩ কোটি টাকা)।</p><p>অংশীদারদের ওয়েবসাইট: <a href=\\"https://www.scrbg.com\\" rel=\\"noopener\\">scrbg.com</a>, <a href=\\"https://www.udccl.com.bd\\" rel=\\"noopener\\">udccl.com.bd</a>, <a href=\\"https://www.rhd.gov.bd\\" rel=\\"noopener\\">rhd.gov.bd</a>, <a href=\\"https://www.cdb.com.cn\\" rel=\\"noopener\\">cdb.com.cn</a>, <a href=\\"https://www.pppo.gov.bd\\" rel=\\"noopener\\">pppo.gov.bd</a>, <a href=\\"https://www.biffl.org.bd\\" rel=\\"noopener\\">biffl.org.bd</a>।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"融资","body":"<p>孟加拉国政府可行性缺口补助最初为22.4亿塔卡，后调整为67.4亿塔卡。国家开发银行贷款161.4亿塔卡（协议于2021年4月签署）；BIFFL贷款107.5亿塔卡，首期4.25亿塔卡于2022年4月发放。融资总额4.12亿美元（约358.5–372.3亿塔卡）。</p><p>合作方网站：<a href=\\"https://www.scrbg.com\\" rel=\\"noopener\\">scrbg.com</a>、<a href=\\"https://www.udccl.com.bd\\" rel=\\"noopener\\">udccl.com.bd</a>、<a href=\\"https://www.rhd.gov.bd\\" rel=\\"noopener\\">rhd.gov.bd</a>、<a href=\\"https://www.cdb.com.cn\\" rel=\\"noopener\\">cdb.com.cn</a>、<a href=\\"https://www.pppo.gov.bd\\" rel=\\"noopener\\">pppo.gov.bd</a>、<a href=\\"https://www.biffl.org.bd\\" rel=\\"noopener\\">biffl.org.bd</a>。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

