INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"পরিচালনা কাঠামো","intro":"","items":[{"meta":"কৌশল","title":"পরিচালনা পর্ষদ","body":"শেয়ারের অনুপাতে সব ইকুইটি অংশীদারের (SRBG, SEL ও UDC) প্রতিনিধি; কৌশলগত দিকনির্দেশনা দেয় এবং বড় সিদ্ধান্ত অনুমোদন করে।"},{"meta":"পরিচালনা","title":"নির্বাহী ব্যবস্থাপনা","body":"প্রধান নির্বাহী কর্মকর্তার নেতৃত্বে প্রধান পরিচালন কর্মকর্তা ও মহাব্যবস্থাপকগণ: দৈনন্দিন পরিচালনা, প্রকল্প বাস্তবায়ন, অংশীজন ব্যবস্থাপনা ও কার্যক্রম প্রতিবেদন।"},{"meta":"পরিপালন","title":"সরকারি তদারকি","body":"সওজ-এর প্রকল্প পরিচালক অগ্রগতি পর্যবেক্ষণ করেন, কনসেশন চুক্তি পরিপালন নিশ্চিত করেন এবং DBEDC ও সরকারি সংস্থার মধ্যে যোগাযোগ রক্ষা করেন।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"治理结构","intro":"","items":[{"meta":"战略","title":"董事会","body":"由各股东（SRBG、SEL和UDC）按持股比例委派代表组成；负责战略指导并审批重大决策。"},{"meta":"运营","title":"执行管理层","body":"由首席执行官领导，首席运营官及各总经理组成：负责日常运营、项目实施、相关方管理和绩效报告。"},{"meta":"合规","title":"政府监督","body":"公路局项目主任监督进度，确保遵守特许经营协议，并负责DBEDC与政府部门之间的联络。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;

