INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"চীনের অবদান","intro":"","items":[{"meta":"অর্থায়ন","title":"আর্থিক বিনিয়োগ","body":"SRBG-এর ৬০% সংখ্যাগরিষ্ঠ অংশ, প্রায় ২৪০ মিলিয়ন মার্কিন ডলার ইকুইটি; চায়না ডেভেলপমেন্ট ব্যাংকের ১,৬১৪ কোটি টাকা (প্রায় ১৯০ মিলিয়ন মার্কিন ডলার) ঋণ; এপ্রিল ২০২১-এ ফাইন্যান্সিয়াল ক্লোজ।"},{"meta":"প্রকৌশল","title":"কারিগরি দক্ষতা","body":"বাংলাদেশে প্রথমবারের মতো সেমি-রিজিড পেভমেন্ট প্রযুক্তি ও রিইনফোর্সড রিটেইনিং ওয়াল ব্যবস্থা, আন্তর্জাতিক মাননিয়ন্ত্রণ ও ট্রাফিক ব্যবস্থাপনা পদ্ধতিসহ।"},{"meta":"বাস্তবায়ন","title":"নির্মাণ ব্যবস্থাপনা","body":"আধুনিক প্রকল্প ব্যবস্থাপনা পদ্ধতি, নির্মাণ পরিকল্পনা ও সময়সূচি, পরিবেশ ব্যবস্থাপনা পরিকল্পনা এবং মান নিশ্চিতকরণ প্রটোকল।"},{"meta":"সক্ষমতা","title":"জ্ঞান স্থানান্তর","body":"চীনে ও প্রকল্প এলাকায় বাংলাদেশি প্রকৌশলীদের প্রশিক্ষণ; আধুনিক মহাসড়ক নির্মাণ পদ্ধতি; পরিচালনা ও রক্ষণাবেক্ষণ জ্ঞান।"},{"meta":"সহযোগিতা","title":"বেল্ট অ্যান্ড রোড ইনিশিয়েটিভ","body":"তৃতীয় বেল্ট অ্যান্ড রোড ফোরামে বাস্তব সহযোগিতা প্রকল্প হিসেবে উপস্থাপিত; দক্ষিণ এশিয়াজুড়ে আঞ্চলিক সংযোগে সহায়ক।"},{"meta":"সম্প্রদায়","title":"সামাজিক দায়বদ্ধতা","body":"প্রাথমিক বিদ্যালয়ে মাল্টিমিডিয়া ক্লাসরুম প্রদান; স্থানীয় এতিমখানায় সহায়তা; কোভিড-১৯ প্রতিরোধ সামগ্রী; স্থানীয় শ্রমিকদের কল্যাণ কর্মসূচি।"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"中方贡献","intro":"","items":[{"meta":"融资","title":"资金投入","body":"SRBG持股60%，股本约2.4亿美元；国家开发银行提供161.4亿塔卡（约1.9亿美元）贷款；2021年4月实现融资关闭。"},{"meta":"工程","title":"技术专长","body":"在孟加拉国首次应用半刚性路面技术和加筋挡土墙体系，并配套国际质量控制标准和交通管理系统。"},{"meta":"实施","title":"施工管理","body":"现代项目管理体系、施工计划与进度安排、环境管理计划和质量保证制度。"},{"meta":"能力","title":"知识转移","body":"在中国及现场培训孟加拉国工程师；现代公路施工方法；运营和养护知识。"},{"meta":"合作","title":"“一带一路”倡议","body":"作为务实合作项目亮相第三届“一带一路”国际合作高峰论坛；促进南亚区域互联互通。"},{"meta":"社区","title":"社会责任","body":"向小学捐赠多媒体教室；资助当地孤儿院；捐赠新冠防疫物资；开展当地员工福利项目。"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;

