INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"সেমি-রিজিড পেভমেন্ট: একটি দৃষ্টান্ত","body":"<p>সেমি-রিজিড পেভমেন্ট পদ্ধতি অ্যাসফল্টের নমনীয়তার সঙ্গে কংক্রিটের দৃঢ়তা যুক্ত করে। SRBG এটি বাস্তবায়ন করেছে এবং চীনে ও প্রকল্প এলাকায় বাংলাদেশি প্রকৌশলীদের প্রশিক্ষণ দিয়েছে। সুফল: প্রচলিত পদ্ধতির তুলনায় সড়কের আয়ু ৩০% পর্যন্ত বৃদ্ধি; বাংলাদেশে সহজলভ্য মিহি বালুর কার্যকর ব্যবহার; কম মেরামতের ফলে জীবনচক্রের ব্যয় হ্রাস; প্রচলিত ইটের ব্যবহার কমানো। কারিগরি নথি ইংরেজি ও বাংলায় সরবরাহ করা হয়েছে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"半刚性路面案例","body":"<p>半刚性路面兼具沥青的柔性与混凝土的强度。SRBG负责实施，并在中国和现场培训孟加拉国工程师。效益：路面寿命比传统做法延长最多30%；有效利用孟加拉国丰富的细砂资源；维修频次降低，全寿命周期成本下降；减少传统砖材用量。技术文件以英文和孟加拉文提供。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

