INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"বাণিজ্য ও ব্যবসা","body":"<p>এক্সপ্রেসওয়েটি গাজীপুরের উৎপাদন কেন্দ্রগুলোকে নারায়ণগঞ্জ হয়ে দক্ষিণের বন্দরগুলোর সঙ্গে যুক্ত করা একটি পণ্যবাহী করিডোর, যা পণ্য পরিবহনের সময় ৭৫% পর্যন্ত কমায়। রপ্তানি জিডিপির ০.৮% বৃদ্ধি এবং পরিবহন খরচ আনুমানিক ১৫–২০% কমার প্রক্ষেপণ রয়েছে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"贸易与商业","body":"<p>本高速公路是一条货运走廊，经纳拉扬甘杰连接加济普尔的制造业中心与南部港口，货运时间最多缩短75%。预计出口将增加相当于GDP的0.8%，运输成本预计下降15–20%。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

