SET @b = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id` JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
  WHERE p.`slug` = 'sustainability' AND b.`type` = 'stat-row' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.stats[0].label')) = 'Freight transport efficiency' LIMIT 1);
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"stats":[{"unit":"%","label":"পণ্য পরিবহনের দক্ষতা","value":"+৬৫"},{"unit":"%","label":"আঞ্চলিক ব্যবসার প্রবৃদ্ধি","value":"+৪২"},{"unit":"%","label":"শিল্প জমির মূল্য","value":"+৮৫"},{"unit":"","label":"নতুন ব্যবসা প্রতিষ্ঠান","value":"+১২০"}]}', 'published' FROM DUAL WHERE @b IS NOT NULL;
