-- sustainability · rich-text · Regional development
SET @b = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id` JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
  WHERE p.`slug` = 'sustainability' AND b.`type` = 'rich-text' AND JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.heading')) = 'Regional development' LIMIT 1);
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"আঞ্চলিক উন্নয়ন","body":"<p>প্রবৃদ্ধির এলাকা: পূর্বাচল অর্থনৈতিক অঞ্চল, জমির মূল্য ৪৬% বৃদ্ধি; গাজীপুর শিল্প করিডোর, ব্যবসায় ৩৮% প্রবৃদ্ধি; নারায়ণগঞ্জ লজিস্টিকস হাব, সক্ষমতা ৫২% সম্প্রসারণ। দীর্ঘমেয়াদি প্রক্ষেপিত প্রভাব: ঢাকার কেন্দ্র থেকে অর্থনৈতিক কর্মকাণ্ডের বিকেন্দ্রীকরণ, পথজুড়ে বিশেষায়িত শিল্প ক্লাস্টার, সম্পত্তির মূল্য ও স্থানীয় রাজস্ব বৃদ্ধি, এবং অন্যান্য পরিকল্পিত অবকাঠামোর সঙ্গে সমন্বয়।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"区域发展","body":"<p>增长区域：Purbachal经济区，地价上涨46%；加济普尔工业走廊，商业增长38%；纳拉扬甘杰物流枢纽，能力扩张52%。预计长期影响：经济活动从达卡核心区向外疏解，沿线形成专业化产业集群，房地产价值和地方税收提升，并与其他规划基础设施形成衔接。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

