INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'bn', '{"heading":"প্রথম অংশ","body":"<p>ভোগড়া (গাজীপুর) থেকে কাঞ্চন পর্যন্ত প্রথম অংশটি ২০২৫ সালের মার্চের শেষে ঈদুল ফিতরের যাত্রীদের জন্য পরীক্ষামূলকভাবে খোলা হয়। ঈদের সময় এটি টোলমুক্ত ছিল এবং ২০ লাখের বেশি যাত্রী এটি ব্যবহার করেন। এর বর্তমান বিস্তার ও অবস্থা এই পাতায় দেখানো আছে।</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`) SELECT @b, 'zh', '{"heading":"首段","body":"<p>自Vogra（加济普尔）至Kanchan的首段于2025年3月下旬开斋节期间试通车，节日期间免收通行费，通行旅客超过200万人次。其当前通车范围和状态见本页。</p>"}', 'published' FROM DUAL WHERE @b IS NOT NULL;

-- Page titles and search descriptions for the three legal pages.
INSERT INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) SELECT p.`id`, 'en', 'Privacy notice', 'How DBEDC collects, uses and protects personal information on this website.', 'published' FROM `pages` p WHERE p.`slug` = 'privacy'
  ON DUPLICATE KEY UPDATE `title` = IF(`title` = '', VALUES(`title`), `title`), `seo_description` = IF(`seo_description` = '', VALUES(`seo_description`), `seo_description`), `page_translations`.`status` = 'published';
INSERT INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) SELECT p.`id`, 'bn', 'গোপনীয়তা বিজ্ঞপ্তি', 'এই ওয়েবসাইটে DBEDC কীভাবে ব্যক্তিগত তথ্য সংগ্রহ, ব্যবহার ও সুরক্ষা করে।', 'published' FROM `pages` p WHERE p.`slug` = 'privacy'
  ON DUPLICATE KEY UPDATE `title` = IF(`title` = '', VALUES(`title`), `title`), `seo_description` = IF(`seo_description` = '', VALUES(`seo_description`), `seo_description`), `page_translations`.`status` = 'published';
