INSERT INTO `page_translations` (`page_id`, `locale`, `title`, `seo_description`, `status`) SELECT p.`id`, 'bn', 'প্রবেশগম্যতা বিবৃতি', 'এই ওয়েবসাইট কতটা প্রবেশগম্য, কোন মানদণ্ডে পরীক্ষা করা হয় এবং কোনো বাধা কীভাবে জানাবেন।', 'published' FROM `pages` p WHERE p.`slug` = 'accessibility'
